  const rowClass =
    "flex w-full items-center gap-3.5 rounded-3xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left shadow-[0_12px_28px_rgba(0,0,0,0.35)] transition active:scale-[0.98]";
